		{"type":"gemini","content":"Let me read that file.","toolCalls":[
			{"id":"tc-1","name":"read_file","args":{"file_path":"/src/main.go"}},
			{"id":"tc-2","name":"run_command","args":{"command":"go build ./..."}}
