	if entries[3].ToolDetail != "go build ./..." {
		t.Errorf("entry 3: expected tool detail 'go build ./...', got %s", entries[3].ToolDetail)
	}
}

func TestBuildCondensedTranscriptFromBytes_GeminiToolCallArgShapes(t *testing.T) {
