		env.WriteFile("feature.go", "package main\n// new feature\n// committed")
		env.GitCommitWithShadowHooks("Add feature", "feature.go")

		// 8. session-end
		if err := env.SimulateOpenCodeSessionEnd(session.ID, session.TranscriptPath); err != nil {
			t.Fatalf("session-end error: %v", err)
		}

		// 9. Verify condensation happened (checkpoint on metadata branch)
		checkpointID := env.TryGetLatestCheckpointID()
		if checkpointID == "" {
			// Debug: dump logs
			logDir := filepath.Join(env.RepoDir, ".entire", "logs")
			entries, _ := os.ReadDir(logDir)
			for _, e := range entries {
				data, _ := os.ReadFile(filepath.Join(logDir, e.Name()))
				t.Logf("LOG %s:\n%s", e.Name(), string(data))
			}
			// Debug: list session states
			sessionDir := filepath.Join(env.RepoDir, ".git", "entire-sessions")
			sessionEntries, _ := os.ReadDir(sessionDir)
